package com.example.orchestration.workflow;import io.temporal.activity.ActivityOptions;import io.temporal.workflow.Workflow;import java.time.Duration;public class OrderLifecycleWorkflowImpl implements OrderLifecycleWorkflow{private final OrderActivities activities=Workflow.newActivityStub(OrderActivities.class,ActivityOptions.newBuilder().setStartToCloseTimeout(Duration.ofSeconds(30)).setRetryOptions(io.temporal.common.RetryOptions.newBuilder().setMaximumAttempts(5).build()).build());private String state="STARTED";public String run(OrderWorkflowRequest r){activities.publish(r,"ORDER_WORKFLOW","STARTED");state="PAYMENT";activities.pay(r);activities.publish(r,"PAYMENT","COMPLETED");String activationId=activities.activate(r);activities.publish(r,"ESIM_ACTIVATION","REQUESTED");String fulfillmentId=activities.fulfill(r);activities.publish(r,"FULFILLMENT","REQUESTED");state="WAITING_FOR_ACTIVATION_AND_DELIVERY";while(true){String a=activities.activationStatus(r.orderId()),f=activities.fulfillmentStatus(r.orderId());if("ACTIVE".equals(a)&&"DELIVERED".equals(f))break;Workflow.sleep(Duration.ofSeconds(5));}activities.publish(r,"DEPENDENCIES","READY");state="STARTING_BILLING";activities.startBilling(r,activationId,fulfillmentId);activities.publish(r,"BILLING","STARTED");state="COMPLETED";activities.publish(r,"ORDER_WORKFLOW","COMPLETED");return state;}public String status(){return state;}}
